def find_triplet(arr):
    max_sum = 0
    for i in range(len(arr)):
        for j in range(i+1, len(arr)):
            for k in range(j+1, len(arr)):
                sum = arr[i] + arr[j] + arr[k]
                if sum > max_sum:
                    max_sum = sum
                    max_indices = [i, j, k]
