def find_longest_chain(pairs):
    # Sort the pairs by their second element (the length) in descending order
    sorted_pairs = sorted(pairs, key=lambda x: x[1], reverse=True)

    current_chain = []
    longest_chain = []

    for pair in sorted_pairs:
        if not current_chain or pair[0] > current_chain[-1][1]:
            current_chain = [pair]
        else:
            last_pair = current_chain[-1]
            if last_pair[1] < pair[0]:
                current_chain.append(last_pair)
            else:
                current_chain.append(pair)

        longest_chain = max(current_chain, longest_chain)

    return longest_chain,llama-chat,code,1,AI

