    Returns the nth polite number.

    A polite number is a positive integer that is not divisible by any prime number less than or equal to its square root.
    """
    if n == 1:
        return 2

    # Try dividing by all primes up to sqrt(n)
    for prime in range(2, int(n**0.5) + 1):
        if n % prime == 0:
            return -1

    # If we reach this point, n is a polite number
    return n,llama-chat,code,1,AI

