def join_tuples(tuple_list):
    result = []
    for i in range(len(tuple_list)):
        curr = tuple_list[i]
        next_idx = i + 1
        while next_idx < len(tuple_list) and curr[0] == tuple_list[next_idx][0]:
            curr += tuple_list[next_idx]
            next_idx += 1
        result.append(curr)
    return result,llama-chat,code,1,AI

