def counting_sort(arr):
    # Initialize a dictionary to count the number of occurrences of each element
    counts = {}
    for ele in arr:
        if ele in counts:
            counts[ele] += 1
        else:
            counts[ele] = 1

    # Initialize an empty list to store the sorted array
    sorted_arr = []

    # Iterate over the counts and add elements to the sorted array
    for ele, count in counts.items():
        for _ in range(count):
            sorted_arr.append(ele)

    return sorted_arr,llama-chat,code,1,AI

def counting_sort(arr):
    # Calculate the number of elements in each bucket
    buckets = [0] * (max(arr) + 1)
    for element in arr:
        buckets[element] += 1

    # Update the counts for each bucket
    for i in range(len(buckets)):
        buckets[i] -= buckets[i-1] if i > 0 else 0

    # Sort the array using the counts
    sorted_array = []
    for i in range(len(arr)):
        while buckets[arr[i]] > 0:
            sorted_array.append(arr[i])
            buckets[arr[i]] -= 1
    return sorted_array,llama-chat,code,1,AI

