def kth_element(arr, k):
    """
    :param arr: a list of integers
    :param k: an integer
    :return: the kth element in the list
    """
    if k == 0:
        return arr[0]
    if k == 1:
        return arr[1]
    if k == len(arr):
        return arr[-1]
    if k < len(arr) / 2:
        return kth_element(arr[:k], k)
    else:
        return kth_element(arr[k:], k - len(arr) / 2),mpt,code,1,AI

def count_rotations(s):
    """
    Count the number of rotations of a binary string with odd value.
    """
    if len(s) == 0:
        return 0
    if len(s) == 1:
        return 1
    if s[0] == s[-1]:
        return 0
    if s[0] == '0':
        return count_rotations(s[1:])
    if s[-1] == '0':
        return count_rotations(s[:-1])
    if s[0] == '1':
        return count_rotations(s[1:]) + count_rotations(s[:-1])
    return 0,mpt,code,1,AI

