def max_profit(prices, k):
    if k == 0:
        return 0
    if k == 1:
        return max(prices) - min(prices)
    max_profit = 0
    for i in range(k):
        max_profit = max(max_profit, prices[i] - prices[i - 1])
    for i in range(k, len(prices)):
        max_profit = max(max_profit, prices[i] - prices[i - k])
    return max_profit,mpt,code,1,AI

def subset_sum(set, sum):
    if sum == 0:
        return True
    if sum < 0:
        return False
    for i in set:
        if subset_sum(set, sum - i):
            return True
    return False,mpt,code,1,AI

