def is_valid(triangle):
    """
    Check if a triangle is valid or not.
    A triangle is valid if the sum of any two sides must be
    greater than the remaining side.
    """
    if len(triangle) < 3:
        return False
    for i in range(len(triangle) - 2):
        if triangle[i] + triangle[i + 1] <= triangle[i + 2]:
            return False
    return True,mpt,code,1,AI

def smallest_prime_divisor(n):
    """
    Returns the smallest prime divisor of n.
    """
    if n == 1:
        return 1
    elif n == 2:
        return 2
    elif n % 2 == 0:
        return 2
    else:
        for i in range(3, int(n ** 0.5) + 1, 2):
            if n % i == 0:
                return i
        return n,mpt,code,1,AI

