def equilibrium_index(arr):
    """
    Find the index of the element in the given array whose left and right sides
    are equal.
    """
    if len(arr) == 1:
        return 0
    elif len(arr) == 2:
        return 1 if arr[0] == arr[1] else 0
    else:
        left_sum = sum(arr[:len(arr)//2])
        right_sum = sum(arr[len(arr)//2:])
        if left_sum == right_sum:
            return len(arr)//2
        elif left_sum > right_sum:
            return equilibrium_index(arr[:len(arr)//2])
        else:
            return equilibrium_index(arr[len(arr)//2:]),mpt,code,1,AI

