def last_pos(arr, x):
    """
    Find the last position of an element in a sorted array.
    """
    if x not in arr:
        return -1
    i = len(arr) - 1
    while i >= 0 and arr[i] == x:
        i -= 1
    return i,mpt,code,1,AI

