def largest_number(digits):
    digits = sorted(digits)
    i = len(digits) - 1
    j = 0
    while i >= 0 and j < len(digits):
        if digits[i] == digits[j]:
            i -= 1
        else:
            break
    return ''.join(str(digits[j:i+1][::-1]))

