def first_missing_positive(numbers):
    n = len(numbers)
    for i in range(n):
        if numbers[i]!= i + 1:
            continue
        for j in range(i + 1, n):
            if numbers[j] == i + 1:
                numbers[i], numbers[j] = numbers[j], numbers[i]
                break
            elif numbers[j] < i + 1:
                numbers[j], numbers[n - 1] = numbers[n - 1], numbers[j]
                n -= 1
                break
    for i in range(n):
        if numbers[i]!= i + 1:
            return i + 1
    return n + 1,mpt-chat,code,1,AI

