def find_kth_element(arr1, arr2, k):
    i, j = 0, 0
    result = []

    while i < len(arr1) and j < len(arr2):
        if arr1[i] < arr2[j]:
            result.append(arr1[i])
            i += 1
        else:
            result.append(arr2[j])
            j += 1

    while len(result) < k:
        result.append(arr1[i])
        i += 1

    while len(result) > k:
        result.pop()

    return result[k-1],mpt-chat,code,1,AI

